import React, { useState } from 'react';
import { JobBoardLogoIcon } from './BrandLogos';
import { NAV_LINKS } from '../data/jobData';
import { ChevronDown, Menu, X, UserPlus, LogIn, LayoutGrid, Sparkles } from 'lucide-react';

export default function Navbar({ onOpenAuthModal }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState(null);

  const toggleDropdown = (label) => {
    setActiveDropdown(activeDropdown === label ? null : label);
  };

  return (
    <header className="sticky top-0 z-50 w-full bg-[#080827]/90 backdrop-blur-md border-b border-white/5 transition-all">
      <div className="max-w-[1280px] mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
        
        {/* Brand Logo */}
        <a href="#home" className="flex items-center gap-2.5 group cursor-pointer">
          <JobBoardLogoIcon className="w-8 h-8 group-hover:scale-105 transition-transform" />
          <span className="text-xl sm:text-2xl font-bold tracking-tight text-white flex items-center">
            Job<span className="text-white font-extrabold">Board</span>
          </span>
        </a>

        {/* Desktop Navigation Links */}
        <nav className="hidden lg:flex items-center gap-6 xl:gap-8">
          {NAV_LINKS.map((item) => (
            <div key={item.label} className="relative group">
              <a
                href={item.href}
                className="text-xs xl:text-[13px] font-semibold text-slate-300 hover:text-white tracking-wide uppercase flex items-center gap-1 py-2 transition-colors"
              >
                {item.label}
                {item.hasDropdown && (
                  <ChevronDown className="w-3.5 h-3.5 text-slate-400 group-hover:text-white transition-transform group-hover:translate-y-0.5" />
                )}
              </a>

              {/* Minimal hover dropdown indicator */}
              {item.hasDropdown && (
                <div className="absolute left-0 top-full hidden group-hover:block w-48 bg-[#0E0E38] border border-white/10 rounded-lg shadow-xl shadow-black/50 py-2 z-50">
                  <a href={item.href} className="block px-4 py-2 text-xs text-slate-300 hover:text-white hover:bg-white/5 transition-colors">
                    Overview
                  </a>
                  <a href={item.href} className="block px-4 py-2 text-xs text-slate-300 hover:text-white hover:bg-white/5 transition-colors">
                    Browse All
                  </a>
                  <a href={item.href} className="block px-4 py-2 text-xs text-slate-300 hover:text-white hover:bg-white/5 transition-colors">
                    Featured
                  </a>
                </div>
              )}
            </div>
          ))}
        </nav>

        {/* Right CTA Controls */}
        <div className="hidden sm:flex items-center gap-2.5">
          {/* Square Action Icon */}
          <button
            type="button"
            aria-label="Toggle layout or quick view"
            className="w-9 h-9 rounded-md bg-[#161642] hover:bg-[#1f1f58] border border-white/10 flex items-center justify-center text-slate-300 hover:text-white transition-colors cursor-pointer"
            onClick={() => onOpenAuthModal?.('quick')}
          >
            <LayoutGrid className="w-4 h-4 text-purple-300" />
          </button>

          {/* Sign Up Button */}
          <button
            type="button"
            onClick={() => onOpenAuthModal?.('signup')}
            className="px-4 py-2 rounded-md bg-[#6338F5] hover:bg-[#7045FF] text-white text-xs font-semibold tracking-wide flex items-center gap-1.5 shadow-md shadow-[#6338F5]/25 transition-all hover:shadow-[#6338F5]/40 active:scale-95 cursor-pointer"
          >
            <UserPlus className="w-3.5 h-3.5" />
            <span>Sign Up</span>
          </button>

          {/* Login Button */}
          <button
            type="button"
            onClick={() => onOpenAuthModal?.('login')}
            className="px-4 py-2 rounded-md bg-[#6338F5] hover:bg-[#7045FF] text-white text-xs font-semibold tracking-wide flex items-center gap-1.5 shadow-md shadow-[#6338F5]/25 transition-all hover:shadow-[#6338F5]/40 active:scale-95 cursor-pointer"
          >
            <LogIn className="w-3.5 h-3.5" />
            <span>login</span>
          </button>
        </div>

        {/* Mobile Hamburger Button */}
        <div className="flex sm:hidden items-center gap-2">
          <button
            type="button"
            onClick={() => onOpenAuthModal?.('login')}
            className="px-3 py-1.5 rounded-md bg-[#6338F5] text-white text-xs font-semibold"
          >
            Login
          </button>
          <button
            type="button"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="p-2 rounded-md bg-[#161642] text-slate-300 hover:text-white"
            aria-label="Toggle mobile menu"
          >
            {mobileMenuOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
          </button>
        </div>
      </div>

      {/* Mobile Drawer Menu */}
      {mobileMenuOpen && (
        <div className="lg:hidden bg-[#0a0a30] border-b border-white/10 px-4 pt-3 pb-6 space-y-3">
          <div className="space-y-1">
            {NAV_LINKS.map((item) => (
              <div key={item.label} className="border-b border-white/5 pb-2">
                <button
                  type="button"
                  onClick={() => toggleDropdown(item.label)}
                  className="w-full flex items-center justify-between text-left text-sm font-semibold text-slate-200 py-1.5"
                >
                  <span>{item.label}</span>
                  {item.hasDropdown && <ChevronDown className="w-4 h-4 text-slate-400" />}
                </button>
                {activeDropdown === item.label && (
                  <div className="pl-4 py-1 space-y-1 text-xs text-slate-400">
                    <a href={item.href} className="block py-1 hover:text-white">Overview</a>
                    <a href={item.href} className="block py-1 hover:text-white">Trending</a>
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="pt-2 flex flex-col gap-2">
            <button
              type="button"
              onClick={() => {
                setMobileMenuOpen(false);
                onOpenAuthModal?.('signup');
              }}
              className="w-full py-2.5 rounded-md bg-[#6338F5] text-white text-center font-semibold text-sm flex items-center justify-center gap-2"
            >
              <UserPlus className="w-4 h-4" />
              Sign Up
            </button>
            <button
              type="button"
              onClick={() => {
                setMobileMenuOpen(false);
                onOpenAuthModal?.('login');
              }}
              className="w-full py-2.5 rounded-md bg-white/10 hover:bg-white/15 text-white text-center font-semibold text-sm flex items-center justify-center gap-2"
            >
              <LogIn className="w-4 h-4" />
              Login
            </button>
          </div>
        </div>
      )}
    </header>
  );
}
